"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { Check, Copy, File } from "./icons";

// Code Block: generated by UIX from the design system. Same variants and sizes as the Figma component.

const KEYWORDS = new Set(["import", "export", "from", "default", "const", "let", "var", "function", "return", "if", "else", "for", "while", "new", "class", "extends", "async", "await", "type", "interface", "true", "false", "null"]);

type Token = { text: string; kind: "keyword" | "string" | "plain" };

// Tiny highlighter: strings and keywords only. Pass your own children for anything fancier.
function tokenize(line: string): Token[] {
  return line.split(/("[^"]*"|'[^']*'|\w+)/).filter(Boolean).map((text) => ({ text, kind: text[0] === '"' || text[0] === "'" ? "string" : KEYWORDS.has(text) ? "keyword" : "plain" }));
}

const codeBlockVariants = cva(
  "flex w-full flex-col overflow-hidden rounded-lg",
  {
    variants: {
      theme: {
        dark: "skin-keep bg-inverse text-fg-inverse [&_[data-slot=header]]:border-current/15 [&_[data-slot=muted]]:opacity-60",
        light: "bg-surface text-fg-primary border border-line-default [&_[data-slot=header]]:bg-subtle [&_[data-slot=header]]:border-line-default [&_[data-slot=muted]]:text-fg-tertiary",
      },
    },
    defaultVariants: {
      theme: "dark",
    },
  },
);

export interface CodeBlockProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "children">,
    VariantProps<typeof codeBlockVariants> {
  /** Source text; each line gets a number and keywords / strings are colored. */
  code: string;
  filename?: React.ReactNode;
  /** Bar with the file name and a copy button. */
  showHeader?: boolean;
  showLineNumbers?: boolean;
}

const CodeBlock = React.forwardRef<HTMLDivElement, CodeBlockProps>(
  ({ className, theme, code, filename, showHeader = true, showLineNumbers = true, ...props }, ref) => {
    const [copied, setCopied] = React.useState(false);
    const lines = code.split("\n");
    return (
      <div data-slot="code-block" data-kind="surface" ref={ref} className={cn(codeBlockVariants({ theme }), className)} {...props}>
        {showHeader ? (
          <div data-slot="header" className="flex items-center justify-between border-b h-[44px] px-4 gap-2">
            <span className="flex items-center gap-2 text-label-small [&_svg]:size-4">
              <File aria-hidden data-slot="muted" />
              {filename}
            </span>
            <button
              type="button"
              aria-label={copied ? "Copied" : "Copy code"}
              onClick={() => {
                navigator.clipboard?.writeText(code);
                setCopied(true);
                window.setTimeout(() => setCopied(false), 1500);
              }}
              className="inline-flex cursor-pointer rounded-xs opacity-70 hover:opacity-100 focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus [&_svg]:size-4"
            >
              {copied ? <Check aria-hidden /> : <Copy aria-hidden />}
            </button>
          </div>
        ) : null}
        <pre tabIndex={0} className="overflow-x-auto p-4 text-code font-mono focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
          <code className="flex flex-col">
            {lines.map((line, index) => (
              <span key={index} className="flex gap-4">
                {showLineNumbers ? <span aria-hidden data-slot="muted" className="w-4 shrink-0 select-none text-right">{index + 1}</span> : null}
                <span className="whitespace-pre">
                  {tokenize(line).map((token, tokenIndex) => (
                    <span key={tokenIndex} className={token.kind === "keyword" ? "text-fg-brand" : token.kind === "string" ? "text-fg-success" : void 0}>
                      {token.text}
                    </span>
                  ))}
                </span>
              </span>
            ))}
          </code>
        </pre>
      </div>
    );
  },
);
CodeBlock.displayName = "CodeBlock";

export { CodeBlock, codeBlockVariants };
